insert into public.battle_challenges (id, tier, title, public_data, review_data) values
  ('maior-de-dois', 1, 'O maior de dois', '{"id":"maior-de-dois","tier":1,"title":"O maior de dois","statement":"Complete `resolver(a, b)` para devolver o **maior** dos dois números.\n\nSe forem iguais, devolva qualquer um deles (são o mesmo valor).","constraints":["-1000 ≤ a, b ≤ 1000"],"signature":{"params":[{"name":"a","type":"int"},{"name":"b","type":"int"}],"returns":"int"},"examples":[{"input":[3,9],"output":"9"},{"input":[-2,-7],"output":"-2"}]}'::jsonb, '{"idea":"Uma única comparação decide: se a for maior que b, a resposta é a; senão, é b.","steps":["Compare a com b usando >.","Devolva o vencedor da comparação (no empate, qualquer um serve)."],"pitfalls":["Esquecer o return e só imprimir o valor.","Comparar textos em vez de números em linguagens que leem tudo como texto."],"study":["condicionais","operadores"]}'::jsonb),
  ('par-ou-impar', 1, 'Par ou ímpar?', '{"id":"par-ou-impar","tier":1,"title":"Par ou ímpar?","statement":"Complete `resolver(n)` para devolver o texto `par` se `n` for par e `impar` (sem acento) se for ímpar.","constraints":["0 ≤ n ≤ 1.000.000"],"signature":{"params":[{"name":"n","type":"int"}],"returns":"str"},"examples":[{"input":[4],"output":"par"},{"input":[7],"output":"impar"}]}'::jsonb, '{"idea":"Um número é par quando o resto da divisão por 2 é zero.","steps":["Calcule n % 2.","Resto 0 → \"par\"; caso contrário → \"impar\"."],"pitfalls":["Negativos: em algumas linguagens -3 % 2 dá -1, então teste se o resto é zero, não se é 1.","Escrever \"ímpar\" com acento."],"study":["condicionais","operadores"]}'::jsonb),
  ('calcular-troco', 1, 'Quanto de troco?', '{"id":"calcular-troco","tier":1,"title":"Quanto de troco?","statement":"Um produto custa `preco` e o cliente pagou `pago` (os dois em centavos). Complete `resolver(preco, pago)` para devolver o troco.\n\nSe o dinheiro **não for suficiente**, devolva `-1`.","constraints":["1 ≤ preco, pago ≤ 100.000"],"signature":{"params":[{"name":"preco","type":"int"},{"name":"pago","type":"int"}],"returns":"int"},"examples":[{"input":[350,500],"output":"150"},{"input":[1000,1000],"output":"0"},{"input":[800,500],"output":"-1"}]}'::jsonb, '{"idea":"Troco é pago menos preço, desde que o pagamento cubra o preço.","steps":["Se pago < preco, devolva -1.","Senão, devolva pago - preco."],"pitfalls":["Inverter a subtração.","Tratar pagamento exato como insuficiente (troco 0 é válido)."],"study":["condicionais","variáveis"]}'::jsonb),
  ('conceito-da-nota', 1, 'Conceito da nota', '{"id":"conceito-da-nota","tier":1,"title":"Conceito da nota","statement":"Complete `resolver(nota)` para devolver o conceito:\n\n`A` para 90 ou mais, `B` de 70 a 89, `C` de 50 a 69 e `D` abaixo de 50.","constraints":["0 ≤ nota ≤ 100"],"signature":{"params":[{"name":"nota","type":"int"}],"returns":"str"},"examples":[{"input":[95],"output":"A"},{"input":[70],"output":"B"},{"input":[12],"output":"D"}]}'::jsonb, '{"idea":"Faixas de valores: teste da maior para a menor e pare na primeira que servir.","steps":["nota >= 90 → A.","senão nota >= 70 → B.","senão nota >= 50 → C.","senão → D."],"pitfalls":["Testar as faixas fora de ordem, fazendo 95 cair em B.","Usar > no lugar de >= nos limites (90, 70, 50)."],"study":["condicionais","else if"]}'::jsonb),
  ('soma-ate-n', 2, 'Soma de 1 até N', '{"id":"soma-ate-n","tier":2,"title":"Soma de 1 até N","statement":"Complete `resolver(n)` para devolver `1 + 2 + 3 + ... + n`.\n\nPara `n = 0`, a soma é `0`.","constraints":["0 ≤ n ≤ 20.000"],"signature":{"params":[{"name":"n","type":"int"}],"returns":"int"},"examples":[{"input":[4],"output":"10"},{"input":[10],"output":"55"}]}'::jsonb, '{"idea":"Um acumulador que começa em 0 e recebe cada número de 1 até n (ou a fórmula n × (n + 1) / 2).","steps":["soma = 0.","Para i de 1 até n, some i.","Devolva soma."],"pitfalls":["Laço que para em n - 1.","Começar a soma em 1 e errar o caso n = 0."],"study":["laços","acumulador"]}'::jsonb),
  ('contar-letra', 2, 'Quantas vezes aparece?', '{"id":"contar-letra","tier":2,"title":"Quantas vezes aparece?","statement":"Complete `resolver(texto, letra)` para contar quantas vezes `letra` (um único caractere) aparece em `texto`.","constraints":["texto tem de 1 a 200 letras minúsculas, sem espaços","letra é uma única letra minúscula"],"signature":{"params":[{"name":"texto","type":"str"},{"name":"letra","type":"str"}],"returns":"int"},"examples":[{"input":["banana","a"],"output":"3"},{"input":["programacao","z"],"output":"0"}]}'::jsonb, '{"idea":"Percorra o texto caractere por caractere e conte as igualdades.","steps":["contador = 0.","Para cada caractere do texto, se for igual à letra, some 1.","Devolva o contador."],"pitfalls":["Comparar maiúscula com minúscula como se fossem iguais.","Contar fora do laço."],"study":["strings","laços"]}'::jsonb),
  ('quantos-digitos', 2, 'Quantos dígitos?', '{"id":"quantos-digitos","tier":2,"title":"Quantos dígitos?","statement":"Complete `resolver(n)` para devolver quantos dígitos `n` tem.\n\nO número `0` tem 1 dígito. Tente resolver com divisões por 10 em um laço.","constraints":["0 ≤ n ≤ 2.000.000.000"],"signature":{"params":[{"name":"n","type":"int"}],"returns":"int"},"examples":[{"input":[2026],"output":"4"},{"input":[7],"output":"1"}]}'::jsonb, '{"idea":"Cada divisão inteira por 10 remove um dígito; conte quantas divisões até chegar a 0.","steps":["Trate n = 0 como 1 dígito.","Enquanto n > 0: n = n / 10 (inteiro) e conte.","Devolva a contagem."],"pitfalls":["Divisão com vírgula (use divisão inteira).","Esquecer o caso zero."],"study":["while","divisão inteira"]}'::jsonb),
  ('palavra-ao-contrario', 2, 'Palavra ao contrário', '{"id":"palavra-ao-contrario","tier":2,"title":"Palavra ao contrário","statement":"Complete `resolver(palavra)` para devolver a palavra escrita de trás para frente.","constraints":["palavra tem de 1 a 100 letras minúsculas"],"signature":{"params":[{"name":"palavra","type":"str"}],"returns":"str"},"examples":[{"input":["codigo"],"output":"ogidoc"},{"input":["arara"],"output":"arara"}]}'::jsonb, '{"idea":"Monte um texto novo lendo a palavra do último caractere para o primeiro.","steps":["Comece com um texto vazio.","Percorra do índice tamanho - 1 até 0, juntando cada caractere.","Devolva o resultado."],"pitfalls":["Começar no índice tamanho (fora da palavra).","Parar antes do índice 0."],"study":["strings","índices"]}'::jsonb),
  ('soma-dos-pares', 3, 'Soma dos pares', '{"id":"soma-dos-pares","tier":3,"title":"Soma dos pares","statement":"Complete `resolver(v)` para devolver a soma dos números **pares** da lista `v`.\n\nLista sem pares (ou vazia) dá `0`. Números negativos também podem ser pares.","constraints":["0 ≤ tamanho de v ≤ 1000","-1000 ≤ v[i] ≤ 1000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int"},"examples":[{"input":[[1,2,3,4]],"output":"6"},{"input":[[-6,5,0]],"output":"-6"}]}'::jsonb, '{"idea":"Filtrar e acumular: some só os itens com resto 0 na divisão por 2.","steps":["soma = 0.","Para cada x da lista, se x % 2 == 0, some x.","Devolva soma."],"pitfalls":["Negativos pares (-4 % 2 é 0, mas teste igualdade com zero).","Somar as posições pares em vez dos valores pares."],"study":["arrays","filter","laços"]}'::jsonb),
  ('menor-e-maior', 3, 'Menor e maior', '{"id":"menor-e-maior","tier":3,"title":"Menor e maior","statement":"Complete `resolver(v)` para devolver uma lista com dois números: o **menor** e o **maior** valor de `v`, nessa ordem.","constraints":["1 ≤ tamanho de v ≤ 1000","-100.000 ≤ v[i] ≤ 100.000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int[]"},"examples":[{"input":[[4,-2,9,0]],"output":"-2 9"},{"input":[[7]],"output":"7 7"}]}'::jsonb, '{"idea":"Uma passada pela lista guardando o menor e o maior vistos até agora.","steps":["Comece menor e maior com o primeiro item.","Para cada item, atualize menor e maior.","Devolva [menor, maior]."],"pitfalls":["Começar com 0, o que quebra listas só de negativos (ou só de positivos grandes).","Inverter a ordem do resultado."],"study":["arrays","laços"]}'::jsonb),
  ('acima-da-media', 3, 'Acima da média', '{"id":"acima-da-media","tier":3,"title":"Acima da média","statement":"Complete `resolver(v)` para contar quantos números de `v` são **maiores** que a média da lista.\n\nDica: dá para evitar números com vírgula comparando `x * tamanho > soma`.","constraints":["1 ≤ tamanho de v ≤ 1000","0 ≤ v[i] ≤ 1000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int"},"examples":[{"input":[[2,4,6]],"output":"1"},{"input":[[5,5,5,5]],"output":"0"}]}'::jsonb, '{"idea":"Duas passadas: primeiro a soma, depois conte quem passa da média.","steps":["Some todos os itens.","Conte os x em que x × tamanho > soma (evita números com vírgula).","Devolva a contagem."],"pitfalls":["Usar >= quando o enunciado pede estritamente maior.","Divisão inteira na média arredondando errado."],"study":["arrays","média"]}'::jsonb),
  ('segundo-maior-distinto', 4, 'O vice-campeão', '{"id":"segundo-maior-distinto","tier":4,"title":"O vice-campeão","statement":"Complete `resolver(v)` para devolver o **segundo maior valor diferente** da lista.\n\nEm `[5, 9, 9, 2]` a resposta é `5`. A lista sempre tem pelo menos dois valores diferentes.","constraints":["2 ≤ tamanho de v ≤ 1000","-10.000 ≤ v[i] ≤ 10.000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int"},"examples":[{"input":[[5,9,9,2]],"output":"5"},{"input":[[1,2]],"output":"1"}]}'::jsonb, '{"idea":"Guarde o maior e o segundo maior, ignorando repetições do maior.","steps":["Ache o maior valor.","Ache o maior entre os valores menores que ele.","Devolva esse segundo."],"pitfalls":["Ordenar e pegar o penúltimo sem tirar repetidos ([5, 9, 9] daria 9).","Começar o segundo maior com 0 quando há negativos."],"study":["arrays","ordenação"]}'::jsonb),
  ('palavra-mais-longa', 4, 'A palavra mais longa', '{"id":"palavra-mais-longa","tier":4,"title":"A palavra mais longa","statement":"Complete `resolver(frase)` para devolver a palavra mais longa da frase.\n\nAs palavras estão separadas por **um** espaço. Em empate, devolva a que aparece primeiro.","constraints":["a frase tem de 1 a 50 palavras de letras minúsculas","cada palavra tem de 1 a 15 letras"],"signature":{"params":[{"name":"frase","type":"str"}],"returns":"str"},"examples":[{"input":["eu gosto de programar"],"output":"programar"},{"input":["sol mar ceu"],"output":"sol"}]}'::jsonb, '{"idea":"Separe a frase em palavras e guarde a mais longa, trocando só quando aparecer uma estritamente maior.","steps":["Divida a frase pelo espaço.","Percorra as palavras guardando a mais longa (troque só com >).","Devolva a guardada."],"pitfalls":["Usar >= e devolver a última em caso de empate.","Esquecer a última palavra ao montar manualmente."],"study":["strings","split"]}'::jsonb),
  ('girar-lista', 4, 'Girar a lista', '{"id":"girar-lista","tier":4,"title":"Girar a lista","statement":"Complete `resolver(v, k)` para mover cada elemento `k` posições para a **direita**; quem sai do fim volta para o começo.\n\n`v = [1, 2, 3, 4]` e `k = 1` dá `[4, 1, 2, 3]`. O `k` pode ser maior que o tamanho.","constraints":["1 ≤ tamanho de v ≤ 1000","0 ≤ k ≤ 1.000.000"],"signature":{"params":[{"name":"v","type":"int[]"},{"name":"k","type":"int"}],"returns":"int[]"},"examples":[{"input":[[1,2,3,4],1],"output":"4 1 2 3"},{"input":[[1,2,3],5],"output":"2 3 1"}]}'::jsonb, '{"idea":"Girar k vezes é o mesmo que girar k % tamanho; o novo início é a parte do fim.","steps":["k = k % tamanho (cuidado com lista vazia).","Resultado = últimos k itens + os primeiros tamanho - k."],"pitfalls":["k maior que o tamanho.","Girar para a esquerda em vez da direita."],"study":["arrays","resto da divisão"]}'::jsonb),
  ('colchetes-balanceados', 5, 'Colchetes em ordem', '{"id":"colchetes-balanceados","tier":5,"title":"Colchetes em ordem","statement":"Complete `resolver(s)` para devolver `true` se todos os `()`, `[]` e `{}` abrem e fecham na ordem certa, e `false` caso contrário.\n\n`{[()]}` está certo; `([)]` e `((` não estão.","constraints":["1 ≤ tamanho de s ≤ 10.000","s só tem os caracteres ()[]{}"],"signature":{"params":[{"name":"s","type":"str"}],"returns":"bool"},"examples":[{"input":["{[()]}"],"output":"true"},{"input":["([)]"],"output":"false"},{"input":["(("],"output":"false"}]}'::jsonb, '{"idea":"Uma pilha: quem abre entra; quem fecha precisa combinar com o topo.","steps":["Para cada símbolo de abertura, empilhe.","Para cada fechamento, a pilha não pode estar vazia e o topo precisa ser o par correspondente.","No fim, a pilha precisa estar vazia."],"pitfalls":["Só contar aberturas e fechamentos (aceitaria \"([)]\").","Não checar a pilha vazia no final (aceitaria \"((\")."],"study":["pilha","estruturas de dados"]}'::jsonb),
  ('busca-na-lista-ordenada', 5, 'Achar na lista ordenada', '{"id":"busca-na-lista-ordenada","tier":5,"title":"Achar na lista ordenada","statement":"A lista `v` está em ordem crescente e não tem repetidos. Complete `resolver(v, alvo)` para devolver a **posição** (começando em 0) de `alvo`, ou `-1` se ele não estiver na lista.\n\nUma busca binária resolve em poucos passos mesmo com listas grandes.","constraints":["1 ≤ tamanho de v ≤ 50.000","-1.000.000 ≤ v[i], alvo ≤ 1.000.000"],"signature":{"params":[{"name":"v","type":"int[]"},{"name":"alvo","type":"int"}],"returns":"int"},"examples":[{"input":[[1,3,5,7,9],7],"output":"3"},{"input":[[2,4],3],"output":"-1"}]}'::jsonb, '{"idea":"Busca binária: compare com o meio e descarte a metade em que o alvo não pode estar.","steps":["inicio = 0, fim = tamanho - 1.","Enquanto inicio <= fim: compare v[meio] com o alvo e mova inicio ou fim.","Sem achar, devolva -1."],"pitfalls":["Laço infinito por não mover inicio/fim além do meio.","Condição < em vez de <= e perder listas de um item."],"study":["busca binária","algoritmos"]}'::jsonb),
  ('compactar-texto', 5, 'Compactar texto', '{"id":"compactar-texto","tier":5,"title":"Compactar texto","statement":"Complete `resolver(s)` para trocar cada sequência de letras iguais pela letra seguida da quantidade.\n\n`aaabcc` vira `a3b1c2`.","constraints":["1 ≤ tamanho de s ≤ 10.000","s só tem letras minúsculas"],"signature":{"params":[{"name":"s","type":"str"}],"returns":"str"},"examples":[{"input":["aaabcc"],"output":"a3b1c2"},{"input":["abc"],"output":"a1b1c1"}]}'::jsonb, '{"idea":"Conte sequências: enquanto a letra se repete, aumente o contador; quando muda, escreva letra + contagem.","steps":["Percorra o texto comparando cada letra com a anterior.","Ao mudar (e no fim), adicione a letra e a contagem.","Devolva o texto montado."],"pitfalls":["Esquecer de escrever a última sequência.","Texto vazio."],"study":["strings","laços"]}'::jsonb),
  ('pares-que-somam', 6, 'Pares que somam o alvo', '{"id":"pares-que-somam","tier":6,"title":"Pares que somam o alvo","statement":"A lista `v` tem números **diferentes**. Complete `resolver(v, alvo)` para contar quantos pares de posições `i < j` têm `v[i] + v[j] == alvo`.\n\nAs listas podem ter 100 mil números: dois laços aninhados estouram o tempo. Pense em guardar o que você já viu.","constraints":["1 ≤ tamanho de v ≤ 100.000","valores distintos entre -1.000.000 e 1.000.000","-2.000.000 ≤ alvo ≤ 2.000.000"],"signature":{"params":[{"name":"v","type":"int[]"},{"name":"alvo","type":"int"}],"returns":"int"},"examples":[{"input":[[1,5,3,7,2],8],"output":"2"},{"input":[[4,6],3],"output":"0"}]}'::jsonb, '{"idea":"Para cada número x, o par que falta é alvo - x. Um conjunto (Set/dicionário) diz na hora se ele já apareceu.","steps":["Percorra a lista uma vez.","Se alvo - x já está no conjunto, conte um par.","Adicione x ao conjunto."],"pitfalls":["Dois laços aninhados: O(n²) estoura o tempo com 100 mil números.","Contar o mesmo par duas vezes."],"study":["dicionário","conjunto","complexidade"]}'::jsonb),
  ('melhor-sequencia', 6, 'A melhor sequência', '{"id":"melhor-sequencia","tier":6,"title":"A melhor sequência","statement":"Complete `resolver(v)` para devolver a **maior soma** de um trecho contínuo (com pelo menos um número) da lista.\n\nEm `[-2, 1, -3, 4, -1, 2, 1, -5, 4]` a resposta é `6` (`4, -1, 2, 1`). Com 100 mil números, testar todos os trechos é lento demais.","constraints":["1 ≤ tamanho de v ≤ 100.000","-10.000 ≤ v[i] ≤ 10.000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int"},"examples":[{"input":[[-2,1,-3,4,-1,2,1,-5,4]],"output":"6"},{"input":[[-3,-1,-2]],"output":"-1"}]}'::jsonb, '{"idea":"Algoritmo de Kadane: o melhor trecho que termina aqui é o item sozinho ou o item somado ao melhor trecho anterior.","steps":["atual = melhor = primeiro item.","Para cada item: atual = max(item, atual + item); melhor = max(melhor, atual).","Devolva melhor."],"pitfalls":["Começar em 0 e errar listas só de negativos.","Testar todos os trechos (O(n²))."],"study":["algoritmos","complexidade"]}'::jsonb),
  ('contar-primos', 6, 'Quantos primos?', '{"id":"contar-primos","tier":6,"title":"Quantos primos?","statement":"Complete `resolver(n)` para devolver quantos números primos existem de `2` até `n` (inclusive).\n\nCom `n` até 2 milhões, testar divisor por divisor é lento. Pesquise o Crivo de Eratóstenes.","constraints":["0 ≤ n ≤ 2.000.000"],"signature":{"params":[{"name":"n","type":"int"}],"returns":"int"},"examples":[{"input":[10],"output":"4"},{"input":[2],"output":"1"}]}'::jsonb, '{"idea":"Crivo de Eratóstenes: marque os múltiplos de cada primo como não primos, de uma vez.","steps":["Crie uma lista de verdadeiro até n.","Para cada i a partir de 2 com i × i <= n, se i é primo, marque i×i, i×i+i, ... como falso.","Conte os verdadeiros de 2 até n."],"pitfalls":["Testar divisores um por um para cada número (lento para 2 milhões).","Contar 0 e 1 como primos."],"study":["algoritmos","laços"]}'::jsonb),
  ('menor-caminho-no-labirinto', 7, 'Saída do labirinto', '{"id":"menor-caminho-no-labirinto","tier":7,"title":"Saída do labirinto","statement":"Um labirinto tem `linhas` × `colunas` casas. O `mapa` traz as linhas uma atrás da outra: a casa da linha `i` e coluna `j` (contando do 0) é `mapa[i * colunas + j]`. `.` é caminho livre e `#` é parede.\n\nVocê começa no canto de cima à esquerda e quer chegar ao canto de baixo à direita, andando para cima, baixo, esquerda ou direita. Complete `resolver(linhas, colunas, mapa)` para devolver o **menor número de passos**, ou `-1` se não houver caminho.\n\nUma busca em largura (BFS) encontra o menor caminho visitando cada casa uma vez só.","constraints":["1 ≤ linhas, colunas ≤ 300","mapa tem linhas × colunas caracteres, só . e #","o começo e o fim são sempre ."],"signature":{"params":[{"name":"linhas","type":"int"},{"name":"colunas","type":"int"},{"name":"mapa","type":"str"}],"returns":"int"},"examples":[{"input":[3,4,".....##....."],"output":"5"},{"input":[2,2,".##."],"output":"-1"},{"input":[1,5,"....."],"output":"4"}]}'::jsonb, '{"idea":"Busca em largura (BFS): explora o labirinto em camadas de distância; a primeira vez que chega à saída é o menor caminho.","steps":["Fila começando na entrada, com distância 1.","Tire da fila, visite os vizinhos livres ainda não visitados com distância + 1.","Ao chegar na saída, devolva a distância; fila vazia → sem caminho."],"pitfalls":["Busca em profundidade (DFS) não garante o menor caminho.","Não marcar visitados e entrar em ciclo."],"study":["grafos","fila","busca em largura"]}'::jsonb),
  ('contar-ilhas', 7, 'Quantas ilhas?', '{"id":"contar-ilhas","tier":7,"title":"Quantas ilhas?","statement":"Um mapa tem `linhas` × `colunas` casas, no mesmo formato do labirinto: a casa da linha `i` e coluna `j` é `mapa[i * colunas + j]`. `#` é terra e `.` é água.\n\nUma **ilha** é um grupo de casas de terra ligadas pelos lados (cima, baixo, esquerda, direita; diagonal não conta). Complete `resolver(linhas, colunas, mapa)` para devolver quantas ilhas existem.\n\nCuidado: com mapas de 300 × 300, recursão muito funda pode estourar a pilha. Uma pilha ou fila sua resolve.","constraints":["1 ≤ linhas, colunas ≤ 300","mapa tem linhas × colunas caracteres, só . e #"],"signature":{"params":[{"name":"linhas","type":"int"},{"name":"colunas","type":"int"},{"name":"mapa","type":"str"}],"returns":"int"},"examples":[{"input":[3,5,"##..##...#..#.."],"output":"3"},{"input":[2,2,"...."],"output":"0"}]}'::jsonb, '{"idea":"Cada vez que encontrar terra não visitada, é uma ilha nova: visite toda a ilha (BFS/DFS) para não contá-la de novo.","steps":["Percorra todas as casas.","Terra não visitada: conte 1 e marque a ilha inteira como visitada.","Devolva a contagem."],"pitfalls":["Considerar diagonais como ligação.","Recursão profunda demais em mapas grandes (prefira uma fila)."],"study":["grafos","busca em largura"]}'::jsonb),
  ('grupos-de-amigos', 7, 'Grupos de amigos', '{"id":"grupos-de-amigos","tier":7,"title":"Grupos de amigos","statement":"Há `n` pessoas numeradas de `0` a `n - 1`. A lista `ligacoes` traz amizades em pares: `ligacoes[0]` é amigo de `ligacoes[1]`, `ligacoes[2]` de `ligacoes[3]`, e assim por diante.\n\nAmigo de amigo fica no mesmo grupo. Complete `resolver(n, ligacoes)` para devolver **quantos grupos** existem (quem não tem amigos forma um grupo sozinho).\n\nCom 100 mil pessoas em fila, recursão funda estoura. Pesquise *union-find* (conjuntos disjuntos).","constraints":["1 ≤ n ≤ 100.000","0 ≤ quantidade de pares ≤ 100.000","0 ≤ ligacoes[i] < n"],"signature":{"params":[{"name":"n","type":"int"},{"name":"ligacoes","type":"int[]"}],"returns":"int"},"examples":[{"input":[5,[0,1,1,2,3,4]],"output":"2"},{"input":[4,[]],"output":"4"}]}'::jsonb, '{"idea":"União de conjuntos (union-find) ou busca em grafo: cada componente conectado é um grupo.","steps":["Cada pessoa começa no próprio grupo.","Para cada amizade, una os grupos das duas pessoas.","Conte quantos representantes distintos sobraram."],"pitfalls":["Esquecer pessoas sem nenhuma amizade (cada uma é um grupo).","Union-find sem compressão de caminho em entradas grandes."],"study":["grafos","estruturas de dados"]}'::jsonb),
  ('formas-de-dar-troco', 8, 'De quantas formas?', '{"id":"formas-de-dar-troco","tier":8,"title":"De quantas formas?","statement":"Você tem moedas dos valores da lista `moedas` (quantas quiser de cada). Complete `resolver(valor, moedas)` para contar de quantas formas diferentes dá para formar exatamente `valor`. A ordem não importa: `1 + 2` e `2 + 1` são a mesma forma.\n\nO número pode ficar enorme: devolva o resto da divisão por `1.000.000.007`. Para `valor = 0` existe 1 forma (não usar moeda nenhuma).","constraints":["0 ≤ valor ≤ 10.000","1 ≤ quantidade de moedas ≤ 50","moedas diferentes, entre 1 e 500"],"signature":{"params":[{"name":"valor","type":"int"},{"name":"moedas","type":"int[]"}],"returns":"int"},"examples":[{"input":[5,[1,2,5]],"output":"4"},{"input":[3,[2]],"output":"0"},{"input":[10,[10]],"output":"1"}]}'::jsonb, '{"idea":"Programação dinâmica: formas[v] acumula as formas de montar v usando as moedas vistas até agora (moeda por fora, valor por dentro, para não contar a ordem).","steps":["formas[0] = 1, o resto 0.","Para cada moeda, para v de moeda até valor: formas[v] += formas[v - moeda].","Devolva formas[valor]."],"pitfalls":["Inverter os laços conta 1+2 e 2+1 como formas diferentes.","Recursão sem memória (lenta)."],"study":["programação dinâmica","arrays"]}'::jsonb),
  ('maior-subsequencia-comum', 8, 'O que as palavras têm em comum', '{"id":"maior-subsequencia-comum","tier":8,"title":"O que as palavras têm em comum","statement":"Uma **subsequência** é o que sobra de um texto quando você apaga algumas letras sem mudar a ordem das outras: `aco` é subsequência de `abaco`.\n\nComplete `resolver(a, b)` para devolver o **tamanho** da maior subsequência que aparece nos dois textos.\n\nEm `programacao` e `pragmatico` a resposta é `7` (por exemplo `prgmaco`). Pesquise programação dinâmica: uma tabela com a resposta de cada par de prefixos.","constraints":["1 ≤ tamanho de a, b ≤ 1500","só letras minúsculas"],"signature":{"params":[{"name":"a","type":"str"},{"name":"b","type":"str"}],"returns":"int"},"examples":[{"input":["programacao","pragmatico"],"output":"7"},{"input":["abc","def"],"output":"0"},{"input":["abcde","ace"],"output":"3"}]}'::jsonb, '{"idea":"Tabela dp[i][j] = tamanho da maior subsequência comum dos prefixos a[0..i) e b[0..j).","steps":["Se a[i-1] == b[j-1]: dp[i][j] = dp[i-1][j-1] + 1.","Senão: dp[i][j] = max(dp[i-1][j], dp[i][j-1]).","A resposta é dp[tamanho a][tamanho b]."],"pitfalls":["Confundir subsequência com trecho contínuo.","Índices deslocados ao montar a tabela."],"study":["programação dinâmica","strings"]}'::jsonb),
  ('mochila', 8, 'A mochila do aventureiro', '{"id":"mochila","tier":8,"title":"A mochila do aventureiro","statement":"Cada item `i` pesa `pesos[i]` e vale `valores[i]`. A mochila aguenta no máximo `capacidade` de peso e cada item só pode ser levado **uma vez**. Complete `resolver(capacidade, pesos, valores)` para devolver o **maior valor total** possível.\n\nPegar sempre o item mais valioso (ou o mais leve) nem sempre dá certo. Pesquise o problema da mochila 0/1.","constraints":["0 ≤ capacidade ≤ 10.000","1 ≤ quantidade de itens ≤ 100","1 ≤ pesos[i], valores[i] ≤ 1000","pesos e valores têm o mesmo tamanho"],"signature":{"params":[{"name":"capacidade","type":"int"},{"name":"pesos","type":"int[]"},{"name":"valores","type":"int[]"}],"returns":"int"},"examples":[{"input":[10,[5,4,6,3],[10,40,30,50]],"output":"90"},{"input":[3,[5],[10]],"output":"0"},{"input":[7,[3,4,5],[30,50,60]],"output":"80"}]}'::jsonb, '{"idea":"Mochila 0/1: melhor[c] = maior valor com capacidade c; cada item é considerado uma vez, percorrendo c de trás para frente.","steps":["melhor = lista de zeros até a capacidade.","Para cada item, para c da capacidade até o peso do item: melhor[c] = max(melhor[c], melhor[c - peso] + valor).","Devolva melhor[capacidade]."],"pitfalls":["Percorrer c para frente usa o mesmo item várias vezes.","Escolher só pelo maior valor por peso (guloso não funciona aqui)."],"study":["programação dinâmica"]}'::jsonb),
  ('maior-subsequencia-crescente', 9, 'A escada mais longa', '{"id":"maior-subsequencia-crescente","tier":9,"title":"A escada mais longa","statement":"Complete `resolver(v)` para devolver o tamanho da maior **subsequência estritamente crescente** de `v` (os números não precisam estar lado a lado, mas precisam manter a ordem).\n\nEm `[10, 9, 2, 5, 3, 7, 101, 18]` a resposta é `4` (por exemplo `2, 3, 7, 18`).\n\nCom 100 mil números, a versão O(n²) estoura o tempo. Existe um jeito O(n log n) com busca binária.","constraints":["1 ≤ tamanho de v ≤ 100.000","-1.000.000 ≤ v[i] ≤ 1.000.000"],"signature":{"params":[{"name":"v","type":"int[]"}],"returns":"int"},"examples":[{"input":[[10,9,2,5,3,7,101,18]],"output":"4"},{"input":[[5,5,5]],"output":"1"},{"input":[[3,1,2]],"output":"2"}]}'::jsonb, '{"idea":"Guarde, para cada tamanho, o menor final possível de uma subsequência crescente; a busca binária acha onde cada número entra (O(n log n)).","steps":["Lista de finais vazia.","Para cada x: ache a primeira posição com final >= x (busca binária); substitua ou adicione no fim.","O tamanho da lista é a resposta."],"pitfalls":["Usar > em vez de >= e aceitar números iguais (precisa ser estritamente crescente).","Solução O(n²) estoura o tempo nas entradas grandes."],"study":["busca binária","programação dinâmica"]}'::jsonb),
  ('salas-de-reuniao', 9, 'Salas de reunião', '{"id":"salas-de-reuniao","tier":9,"title":"Salas de reunião","statement":"A reunião `i` começa em `inicio[i]` e termina em `fim[i]`. Uma sala só recebe uma reunião por vez, mas a que termina no instante `10` libera a sala para outra que começa no `10`.\n\nComplete `resolver(inicio, fim)` para devolver o **menor número de salas** que comporta todas as reuniões.\n\nDica: ordenar os começos e os fins separadamente resolve em O(n log n).","constraints":["1 ≤ quantidade de reuniões ≤ 100.000","0 ≤ inicio[i] < fim[i] ≤ 1.000.000.000"],"signature":{"params":[{"name":"inicio","type":"int[]"},{"name":"fim","type":"int[]"}],"returns":"int"},"examples":[{"input":[[0,5,15],[30,10,20]],"output":"2"},{"input":[[1,10],[10,20]],"output":"1"},{"input":[[1,2,3],[10,10,10]],"output":"3"}]}'::jsonb, '{"idea":"Ordene inícios e fins separadamente e varra o tempo: cada início ocupa uma sala, cada fim libera uma; o pico é a resposta.","steps":["Ordene os inícios e os fins.","Avance com dois ponteiros: se o próximo início é menor que o próximo fim, mais uma sala; senão, libere uma.","Guarde o maior número de salas ocupadas."],"pitfalls":["Tratar fim e início no mesmo instante como conflito (o enunciado diz que libera).","Comparar cada par de reuniões (O(n²))."],"study":["ordenação","algoritmos"]}'::jsonb),
  ('subarrays-com-soma-k', 9, 'Trechos que somam K', '{"id":"subarrays-com-soma-k","tier":9,"title":"Trechos que somam K","statement":"Complete `resolver(v, k)` para contar quantos **trechos contínuos** (com pelo menos um número) de `v` têm soma exatamente `k`.\n\nEm `[1, -1, 0]` com `k = 0` há 3: `[1, -1]`, `[0]` e `[1, -1, 0]`.\n\nOs números podem ser negativos, então a técnica de janela deslizante não funciona. Pense em **somas de prefixo** guardadas num mapa.","constraints":["1 ≤ tamanho de v ≤ 100.000","-1000 ≤ v[i] ≤ 1000","-100.000.000 ≤ k ≤ 100.000.000"],"signature":{"params":[{"name":"v","type":"int[]"},{"name":"k","type":"int"}],"returns":"int"},"examples":[{"input":[[1,1,1],2],"output":"2"},{"input":[[1,-1,0],0],"output":"3"},{"input":[[3,4,7,-2,2],7],"output":"3"}]}'::jsonb, '{"idea":"Somas de prefixo: um trecho soma k quando prefixo_atual - prefixo_anterior = k. Um dicionário conta quantas vezes cada prefixo já apareceu.","steps":["contagem = {0: 1}, soma = 0, resposta = 0.","Para cada x: soma += x; resposta += contagem[soma - k]; contagem[soma] += 1.","Devolva resposta."],"pitfalls":["Janela deslizante não funciona com números negativos.","Esquecer o prefixo vazio (contagem[0] = 1)."],"study":["dicionário","somas de prefixo","algoritmos"]}'::jsonb)
